#
# Islands get a map (land tiles, pond, plants, season) and buildings a facing.
# Islands made before this get the classic shape, with each building moved onto
# its classic lot (the old x/y were placeholders the game never used).

from django.db import migrations, models

CLASSIC_LAND = ["...................."] + [".##################."] * 12 + ["...................."]
CLASSIC_LOTS = {"mailbox": (3, 2, 0), "workshop": (8, 2, 0), "lab": (13, 2, 0), "courthouse": (15, 8, 3),
                "post_office": (2, 8, 1)}


def classic_map(apps, schema_editor):
    Island = apps.get_model("mii", "Island")
    Building = apps.get_model("mii", "Building")
    for island in Island.objects.all():
        if island.map:
            continue
        island.map = {"version": 1, "shape": "classic", "land": CLASSIC_LAND,
                         "pond": {"x": 7, "y": 6, "w": 5, "h": 2}, "plants": None, "season": "summer"}
        island.save(update_fields=["map"])
        for b in Building.objects.filter(island_id=island.id):
            if b.type in CLASSIC_LOTS:
                b.x, b.y, b.facing = CLASSIC_LOTS[b.type]
                b.save(update_fields=["x", "y", "facing"])


class Migration(migrations.Migration):

    dependencies = [
        ('mii', '0009_friendship'),
    ]

    operations = [
        migrations.AddField(
            model_name='building',
            name='facing',
            field=models.IntegerField(default=0),
        ),
        migrations.AddField(
            model_name='island',
            name='map',
            field=models.JSONField(default=dict),
        ),
        migrations.RunPython(classic_map, migrations.RunPython.noop),
    ]
